import{_ as n,C as r,o as s,c as i,a3 as e,E as o}from"./chunks/framework.CZBGEXos.js";const m=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"en/getting-started.md","filePath":"en/getting-started.md"}'),l={name:"en/getting-started.md"};function h(d,t,p,c,g,u){const a=r("Screenshot");return s(),i("div",null,[t[0]||(t[0]=e('<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>Sentaro is a crypto monitoring workspace. It reads publicly available market data from Bybit, Binance, Gate.io, OKX and Hyperliquid (plus Kraken spot in <a href="/manual/en/tools/ticks.html">Ticks</a>) and presents it through a set of purpose-built tools.</p><p>You can use it two ways, with the same account and the same tools:</p><table tabindex="0"><thead><tr><th></th><th>Web app</th><th>Windows app</th></tr></thead><tbody><tr><td>Where</td><td><a href="https://app.sentaro.trade/" target="_blank" rel="noreferrer">app.sentaro.trade</a> in any browser</td><td>Downloaded from <a href="https://sentaro.trade/" target="_blank" rel="noreferrer">sentaro.trade</a></td></tr><tr><td>Systems</td><td>Windows, macOS, Linux</td><td>Windows only</td></tr><tr><td>Install</td><td>Nothing to install</td><td>One installer, updates itself</td></tr><tr><td>Layout</td><td>One tool on screen at a time, switched from the top bar</td><td>Each tool in its own window, arranged freely</td></tr><tr><td><a href="/manual/en/tools/terminal.html">Terminal</a></td><td>Not available</td><td>Available (experimental)</td></tr></tbody></table><p>You can use either, or both at once. Your settings are kept separately by each: the web app stores them in your browser, the Windows app on your computer.</p><h2 id="account" tabindex="-1">Account <a class="header-anchor" href="#account" aria-label="Permalink to &quot;Account&quot;">​</a></h2><p>Sentaro uses an email and password account. Signing up sends a 6-digit verification code to your email; enter it to confirm the address, then sign in. You&#39;ll also need to accept the Terms of Service during sign-up.</p><p>Access is free for everyone while Sentaro is in beta. Your status reads <strong>Beta test</strong>: in the web app&#39;s account menu (the round button at the top right), and in the Windows app&#39;s <strong>Home</strong> tab, along with your email and the installed app version. In the Windows app your email is masked by default — click the eye icon next to it to reveal it.</p><div class="tip custom-block"><p class="custom-block-title">Sentaro never touches your exchange accounts</p><p>Every monitoring tool reads public market data only. Sentaro does not ask for exchange API keys, does not connect to your exchange account, and cannot place trades on any of the exchanges it monitors.</p><p>The one exception is the experimental <a href="/manual/en/tools/terminal.html">Terminal</a> in the Windows app, a separate opt-in tool that connects to Hyperliquid, Binance or Bybit with credentials you provide. It does nothing unless you deliberately set it up.</p></div><h2 id="the-web-app" tabindex="-1">The web app <a class="header-anchor" href="#the-web-app" aria-label="Permalink to &quot;The web app&quot;">​</a></h2>',10)),o(a,{src:"web-monitor",alt:"The Sentaro web app showing Monitor",caption:"The web app — Monitor open, the tool's toolbar under the top bar"}),t[1]||(t[1]=e('<p>Open <a href="https://app.sentaro.trade/" target="_blank" rel="noreferrer">app.sentaro.trade</a> and sign in.</p><h3 id="top-bar" tabindex="-1">Top bar <a class="header-anchor" href="#top-bar" aria-label="Permalink to &quot;Top bar&quot;">​</a></h3><ul><li><strong>Tools</strong> — Knives, Spreads, Analyzer, Monitor and Ticks. Click one to switch. The web app remembers the last tool you had open.</li><li><strong>Search</strong> (<kbd>Ctrl</kbd> <kbd>K</kbd>) — open a tool, a tool&#39;s settings, the general settings or this manual by typing its name.</li><li><strong>Settings</strong> (the sliders icon) — the general settings: language, accent color, charts, drawing, and <a href="#new-listing-pop-ups">new-listing pop-ups</a>.</li><li><strong>Help</strong> — links to this manual.</li><li><strong>Account</strong> — your email, your beta status, and <strong>Sign out</strong>.</li></ul><h3 id="tool-toolbar" tabindex="-1">Tool toolbar <a class="header-anchor" href="#tool-toolbar" aria-label="Permalink to &quot;Tool toolbar&quot;">​</a></h3><p>Under the top bar each tool has its own toolbar. The chips in it are <strong>quick filters</strong>: each shows a setting in force (for example <code>Spread ≥ 1%</code> or <code>1m chart</code>) and opens a small popover to change it in place. The icon at the right end opens that tool&#39;s full settings in a side panel. Changes apply at once.</p><h3 id="one-tab-per-tool" tabindex="-1">One tab per tool <a class="header-anchor" href="#one-tab-per-tool" aria-label="Permalink to &quot;One tab per tool&quot;">​</a></h3><p>Each tool streams from Sentaro&#39;s servers, and one account can have each tool open in one place at a time. If you open the same tool in another browser tab or on another device, the first one says the tool <em>was opened in another tab or on another device</em>, with a <strong>Use here</strong> button to take it back.</p><h3 id="drawing-in-fullscreen" tabindex="-1">Drawing in fullscreen <a class="header-anchor" href="#drawing-in-fullscreen" aria-label="Permalink to &quot;Drawing in fullscreen&quot;">​</a></h3><p>The fullscreen chart in Knives, Monitor and Spreads has the drawing tools: horizontal ray, trend line, rectangle, pencil and dissolving pencil, plus the magnet. They use the same shortcuts as the Windows app (see <a href="/manual/en/customize/chart-colors.html">Charts &amp; drawing</a>). Drawings are saved in your browser, per coin and exchange, and show on that coin&#39;s card charts too.</p><h2 id="the-windows-app" tabindex="-1">The Windows app <a class="header-anchor" href="#the-windows-app" aria-label="Permalink to &quot;The Windows app&quot;">​</a></h2><h3 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h3><ol><li>Download the installer with the <strong>Download for Windows</strong> button on <a href="https://sentaro.trade/" target="_blank" rel="noreferrer">sentaro.trade</a>.</li><li>Run the <code>.exe</code>.</li></ol><h4 id="the-smartscreen-warning" tabindex="-1">The SmartScreen warning <a class="header-anchor" href="#the-smartscreen-warning" aria-label="Permalink to &quot;The SmartScreen warning&quot;">​</a></h4><p>On first download and run, <strong>Windows Defender SmartScreen may warn that the app is unrecognized</strong>. This is expected and is not a virus detection.</p><p>SmartScreen flags any new application that has not yet built up a reputation with Microsoft — it simply means not enough people have downloaded the file yet for it to be trusted automatically. Every new indie app goes through this, and the warning disappears on its own as the download count grows.</p><p>To get past it:</p><ol><li>Click <strong>More info</strong> on the SmartScreen popup.</li><li>Click <strong>Run anyway</strong>.</li><li>This only happens once — later launches won&#39;t show the warning.</li></ol><h3 id="first-run" tabindex="-1">First run <a class="header-anchor" href="#first-run" aria-label="Permalink to &quot;First run&quot;">​</a></h3><p>On launch Sentaro checks for updates before anything else, then asks you to sign in.</p><h3 id="the-workspace" tabindex="-1">The workspace <a class="header-anchor" href="#the-workspace" aria-label="Permalink to &quot;The workspace&quot;">​</a></h3>',20)),o(a,{src:"workspace",alt:"The full Sentaro workspace with several tool windows open",caption:"A Sentaro workspace — several tool windows arranged around the main window"}),t[2]||(t[2]=e('<p>The Windows app is built around one small <strong>main window</strong> plus one window per tool.</p><p>The main window&#39;s left edge is a vertical tab bar:</p><table tabindex="0"><thead><tr><th>Tab</th><th>What it holds</th></tr></thead><tbody><tr><td>Home</td><td>Account, language, accent color, chart and drawing settings, new-listing pop-ups</td></tr><tr><td>Knives</td><td><a href="/manual/en/tools/knives.html">Knives</a> settings + its <strong>Open Window</strong> button</td></tr><tr><td>Spreads</td><td><a href="/manual/en/tools/spreads.html">Spreads</a> settings + its <strong>Open Window</strong> button</td></tr><tr><td>Analyzer</td><td><a href="/manual/en/tools/analyzer.html">Analyzer</a> notices + its <strong>Open Window</strong> button</td></tr><tr><td>Monitor</td><td><a href="/manual/en/tools/monitor.html">Monitor</a> settings + its <strong>Open Window</strong> button</td></tr><tr><td>Terminal</td><td><a href="/manual/en/tools/terminal.html">Terminal</a> settings + its <strong>Open Window</strong> button</td></tr><tr><td>Ticks</td><td><a href="/manual/en/tools/ticks.html">Ticks</a> settings + its <strong>Open Window</strong> button</td></tr></tbody></table><p>Every tool works the same way: <strong>its settings live in the main window, and the tool itself opens as a separate window.</strong> Click <strong>Open Window</strong> in a tool&#39;s tab to launch it. While that window is open the button reads <strong>Already Open</strong> and is inert — each tool is limited to one window at a time.</p><p>Because each tool is an independent window, you can size and position them freely to build the layout you want, and leave the main window tucked away.</p><p>Changes to settings apply live — the open tool window picks them up without a restart. Settings are written to disk automatically as you change them.</p><h4 id="titlebar" tabindex="-1">Titlebar <a class="header-anchor" href="#titlebar" aria-label="Permalink to &quot;Titlebar&quot;">​</a></h4><p>Tool windows use Sentaro&#39;s own titlebar rather than the Windows one. It shows <code>SENTARO</code> and the active tool name on the left, and minimize / maximize / close on the right. Drag anywhere on the empty part of the bar to move the window.</p><h3 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h3><p>The Windows app updates itself. On every launch it checks for a new version before showing the sign-in screen; if one exists it downloads, installs and restarts automatically. You&#39;ll see <code>Checking for updates...</code> and then <code>Updating to v&lt;version&gt;...</code> on the loading screen while this happens.</p><p>There is nothing to do manually. The installed version is shown in the <strong>Home</strong> tab as <strong>App Version</strong>. The web app is always the latest version.</p><h2 id="new-listing-pop-ups" tabindex="-1">New-listing pop-ups <a class="header-anchor" href="#new-listing-pop-ups" aria-label="Permalink to &quot;New-listing pop-ups&quot;">​</a></h2><p>When a coin starts trading on one of the monitored exchanges, a pop-up appears with the exchange and the symbol, whichever tool you have open:</p><ul><li><strong>Web app</strong> — in the bottom-right corner of the page, while the Sentaro tab is the one on screen. A listing that arrives while the tab is in the background is not shown later.</li><li><strong>Windows app</strong> — in the bottom-right corner of your screen, above other windows, even when Sentaro is in the background.</li></ul><p><strong>Copy</strong> puts the symbol on your clipboard. A pop-up stays for 20 seconds, and for as long as your pointer is on it; <strong>×</strong> closes it. Up to four show at once — a fifth replaces the oldest.</p><p>A coin is announced once per exchange per day, so a symbol an exchange briefly drops and relists does not come back as new. Pop-ups are live only: there is no history of past listings.</p><p>Settings, under <strong>New listings</strong> in the general settings (web) or the <strong>Home</strong> tab (Windows):</p><ul><li><strong>Listing alert sound</strong> — plays a sound with each pop-up. On by default.</li><li><strong>Test pop-up</strong> — <strong>Send test</strong> shows a sample pop-up for SOLUSDT on Bybit, sent through the server, so you can check that pop-ups and sound work.</li></ul><h2 id="sounds" tabindex="-1">Sounds <a class="header-anchor" href="#sounds" aria-label="Permalink to &quot;Sounds&quot;">​</a></h2><p>Every alert has its own sound, so you can tell what happened without looking:</p><table tabindex="0"><thead><tr><th>Sound</th><th>Plays when</th></tr></thead><tbody><tr><td>Rise</td><td><a href="/manual/en/tools/knives.html">Knives</a>: a coin passes your % threshold</td></tr><tr><td>Chime</td><td>Knives: a coin passes the high threshold</td></tr><tr><td>Duo pluck</td><td><a href="/manual/en/tools/monitor.html">Monitor</a>: NATR or % change threshold met; <a href="/manual/en/tools/spreads.html">Spreads</a>: a new spread opens</td></tr><tr><td>Blip</td><td><a href="/manual/en/tools/ticks.html">Ticks</a>: a big trade</td></tr><tr><td>Fall</td><td>Ticks: a liquidation</td></tr><tr><td>Ding-dong</td><td>A <a href="#new-listing-pop-ups">new-listing pop-up</a></td></tr></tbody></table><p>Each one is switched on or off in its tool&#39;s settings. A browser plays sound only after you have clicked somewhere on the page once.</p><h2 id="language" tabindex="-1">Language <a class="header-anchor" href="#language" aria-label="Permalink to &quot;Language&quot;">​</a></h2><p>Sentaro&#39;s interface is available in English, Українська and Русский. Switch it in the general settings (web) or the <strong>Home</strong> tab (Windows), at the top. This setting is independent of the language you&#39;re reading this manual in.</p><h2 id="accent-color" tabindex="-1">Accent color <a class="header-anchor" href="#accent-color" aria-label="Permalink to &quot;Accent color&quot;">​</a></h2><p>In the general settings (web) or the <strong>Home</strong> tab (Windows), the row of color swatches sets the app-wide accent color: Amber (the default), Green, Blue, Purple, Red, Teal, Pink and White. It applies across every tool.</p><p>This is separate from candle and metric colors — see <a href="/manual/en/customize/chart-colors.html">Charts &amp; drawing</a> for those.</p><h2 id="error-messages" tabindex="-1">Error messages <a class="header-anchor" href="#error-messages" aria-label="Permalink to &quot;Error messages&quot;">​</a></h2><p>When something goes wrong — a feed disconnects, a window fails to open, saved settings can&#39;t be loaded — a short message appears in the bottom-right corner. It disappears on its own after a few seconds, or click <strong>×</strong> to dismiss it. The same message is not repeated more than once every 15 seconds, so a connection that keeps retrying won&#39;t flood the screen.</p><p>If an error keeps coming back, report it in the <a href="https://t.me/sentaro_trade" target="_blank" rel="noreferrer">Telegram group</a> with the exact text.</p><h2 id="getting-help" tabindex="-1">Getting help <a class="header-anchor" href="#getting-help" aria-label="Permalink to &quot;Getting help&quot;">​</a></h2><p>Bug reports and feature requests go to the <a href="https://t.me/sentaro_trade" target="_blank" rel="noreferrer">Telegram group</a> — it&#39;s the fastest way to get a direct response.</p>',32))])}const b=n(l,[["render",h]]);export{m as __pageData,b as default};
